}

function toInternal(href) {
  let path = decodeXml(String(href || "")).trim();
  const absolute = path.match(/^https?:\/\/[^/]+(\/.*)$/i);
  if (absolute) path = absolute[1];
  if (!path.startsWith("/")) path = `/${path}`;
